node -e "
const fs = require('fs');
const path = require('path');

const TESTBED = '/workspace/testbed';
const sender = 'olivia.hr.manager';
const recipient = 'priya.it.lead';
const subject = 'Re: High Priority: Onboarding Equipment Setup Needed - Follow-Up';
const content = fs.readFileSync('/workspace/drafts/follow_up_onboarding_equipment.eml', 'utf8');

// Parse just the body from the draft (skip headers)
const body = content.split('\n\n').slice(1).join('\n\n');

const eml = [
  'From: ' + sender + '@example.com',
  'To: ' + recipient + '@example.com',
  'Subject: ' + subject,
  'Content-Type: text/plain; charset=\"utf-8\"',
  'Content-Transfer-Encoding: 7bit',
  'MIME-Version: 1.0',
  '',
  body
].join('\n');

for (const folder of [sender, recipient]) {
  const dir = path.join(TESTBED, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, subject + '.eml'), eml);
}

console.log('OBSERVATION: Successfully sent email to ' + recipient + '.');
"
